import { useState } from "react";
import axios from "axios";
import { ArrowLeft, BellRing, Send } from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
const field="mt-1 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-100";
export default function NewNotificationForm(){const navigate=useNavigate(),[form,setForm]=useState({title:"",message:"",type:"announcement",audience:"all"}),[sending,setSending]=useState(false);const update=e=>setForm(x=>({...x,[e.target.name]:e.target.value}));const submit=async e=>{e.preventDefault();setSending(true);try{await axios.post("/admin/notifications",form);toast.success("Notification sent to players.");navigate("/notifications")}catch(error){toast.error(error.response?.data?.message||error.response?.data?.errors?.[0]?.message||"Unable to send notification.")}finally{setSending(false)}};return <div className="mx-auto w-full max-w-4xl p-4 sm:p-7"><Link to="/notifications" className="inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-purple-600"><ArrowLeft size={17}/>Back to notifications</Link><section className="mt-5 overflow-hidden rounded-3xl border border-purple-100 bg-white shadow-sm"><header className="bg-gradient-to-r from-purple-700 to-fuchsia-500 p-6 text-white sm:p-8"><BellRing size={30}/><h1 className="mt-4 text-2xl font-black">Send player notification</h1><p className="mt-1 text-sm text-purple-100">Messages appear in the notification centre and unread bell count for matching players.</p></header><form onSubmit={submit} className="space-y-5 p-5 sm:p-8"><label className="block text-sm font-bold">Title<input required minLength="3" maxLength="160" name="title" value={form.title} onChange={update} placeholder="What should players know?" className={field}/></label><label className="block text-sm font-bold">Message<textarea required minLength="5" maxLength="3000" rows="6" name="message" value={form.message} onChange={update} placeholder="Write a clear, helpful message..." className={field}/><span className="mt-1 block text-right text-xs font-normal text-slate-400">{form.message.length}/3000</span></label><div className="grid gap-5 sm:grid-cols-2"><label className="block text-sm font-bold">Notification type<select name="type" value={form.type} onChange={update} className={field}><option value="announcement">Announcement</option><option value="achievement">Achievement</option><option value="reminder">Reminder</option><option value="system">System update</option></select></label><label className="block text-sm font-bold">Target audience<select name="audience" value={form.audience} onChange={update} className={field}><option value="all">All players</option><option value="verified">Verified players</option><option value="unverified">Players awaiting verification</option></select></label></div><div className="rounded-xl bg-purple-50 p-4 text-sm text-purple-800"><b>Delivery:</b> This notification will be published immediately to {form.audience==="all"?"every player":form.audience==="verified"?"verified players":"players who have not completed verification"}.</div><div className="flex justify-end"><button disabled={sending} className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-purple-600 px-6 py-3 font-bold text-white disabled:opacity-60 sm:w-auto"><Send size={17}/>{sending?"Sending...":"Send notification"}</button></div></form></section></div>}
