import React,{useEffect,useState}from"react";import axios from"axios";import{Eye,Pencil,Plus,Trash2}from"lucide-react";import{useNavigate}from"react-router-dom";import{toast}from"react-toastify";import PageNavigation from"../../components/page-navigation";import ConfirmDialog from"../../components/confirm-dialog";import FormDialog from"../../components/form-dialog";import ImageUploadField from"../../components/image-upload-field";import{removeCatalogImage,uploadCatalogImage}from"../../data/media";
const blank={title:"",tag:"",description:"",imageUrl:"",programType:"learn"},field="mt-2 w-full rounded-xl border bg-slate-50 px-4 py-3 outline-none focus:border-purple-500";
export default function Programs(){const nav=useNavigate(),[items,setItems]=useState([]),[loading,setLoading]=useState(true),[dialog,setDialog]=useState(false),[editing,setEditing]=useState(null),[deleting,setDeleting]=useState(null),[form,setForm]=useState(blank),[file,setFile]=useState(null),[busy,setBusy]=useState(false);const load=()=>{setLoading(true);axios.get("/admin/catalog/programs").then(r=>setItems(r.data.programs||[])).catch(e=>toast.error(e.response?.data?.message||"Unable to load categories")).finally(()=>setLoading(false))};useEffect(load,[]);const open=(x=null)=>{setEditing(x);setForm(x?{title:x.title,tag:x.tag||"",description:x.description||"",imageUrl:x.image_url,programType:x.program_type}:blank);setFile(null);setDialog(true)};const save=async e=>{e.preventDefault();setBusy(true);let uploaded="";try{uploaded=file?await uploadCatalogImage(file):"";const payload={...form,imageUrl:uploaded||form.imageUrl};if(!payload.imageUrl)throw Error("Card image is required.");editing?await axios.put(`/admin/catalog/programs/${editing.id}`,payload):await axios.post("/admin/catalog/programs",payload);if(uploaded&&form.imageUrl)await removeCatalogImage(form.imageUrl).catch(()=>{});setDialog(false);load()}catch(x){if(uploaded)await removeCatalogImage(uploaded).catch(()=>{});toast.error(x.response?.data?.message||x.message)}finally{setBusy(false)}};const remove=async()=>{setBusy(true);try{await axios.delete(`/admin/catalog/programs/${deleting.id}`);setDeleting(null);load()}finally{setBusy(false)}};const go=x=>x.program_type==="games"?nav("/categories/age-groups"):nav(`/categories/learn?program=${x.id}`);
return <div className="mx-auto w-full max-w-7xl px-6 pb-10"><PageNavigation items={[{label:"Categories & Levels"}]} title="Categories & Levels" description="Manage game and curriculum learning paths." action={<button onClick={()=>open()} className="flex items-center gap-2 rounded-xl bg-purple-600 px-5 py-3 font-bold text-white"><Plus size={18}/>Add Category</button>}/>{loading?<div className="rounded-2xl bg-white p-16 text-center">Loading…</div>:<div className="overflow-hidden rounded-2xl border bg-white shadow-sm"><table className="w-full text-left"><thead className="bg-slate-50 text-sm text-slate-500"><tr><th className="px-6 py-4">Card</th><th className="px-6 py-4">Tag</th><th className="px-6 py-4">Description</th><th className="px-6 py-4">Type</th><th className="px-6 py-4 text-right">Actions</th></tr></thead><tbody className="divide-y">{items.map(x=><tr key={x.id}><td className="px-6 py-4"><div className="flex items-center gap-3"><img src={x.image_url} alt="" className="h-14 w-20 rounded-lg object-cover"/><b>{x.title}</b></div></td><td className="px-6 py-4 text-sm">{x.tag||"—"}</td><td className="max-w-md px-6 py-4 text-sm text-slate-600">{x.description||"—"}</td><td className="px-6 py-4 capitalize">{x.program_type}</td><td className="px-6 py-4"><div className="flex justify-end gap-3"><button onClick={()=>go(x)} className="flex gap-1"><Eye size={16}/>Open</button><button onClick={()=>open(x)} className="flex gap-1 text-purple-600"><Pencil size={16}/>Edit</button><button onClick={()=>setDeleting(x)} className="flex gap-1 text-red-500"><Trash2 size={16}/>Delete</button></div></td></tr>)}</tbody></table></div>}<FormDialog open={dialog} title={editing?"Edit category":"Add category"} onClose={()=>setDialog(false)}><form onSubmit={save} className="space-y-4"><label className="block text-sm font-semibold">Card title *<input required className={field} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>{!editing&&<label className="block text-sm font-semibold">Path type<select className={field} value={form.programType} onChange={e=>setForm({...form,programType:e.target.value})}><option value="learn">Curriculum learning</option><option value="games">Age-group games</option></select></label>}<label className="block text-sm font-semibold">Card tag (optional)<input className={field} value={form.tag} onChange={e=>setForm({...form,tag:e.target.value})}/></label><label className="block text-sm font-semibold">Description (optional)<textarea rows="3" className={field} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div><span className="text-sm font-semibold">Card image *</span><ImageUploadField file={file} currentUrl={form.imageUrl} onChange={setFile}/></div><button disabled={busy} className="w-full rounded-xl bg-purple-600 py-3 font-bold text-white">{busy?"Saving…":"Save"}</button></form></FormDialog><ConfirmDialog open={!!deleting} loading={busy} onCancel={()=>setDeleting(null)} onConfirm={remove} title="Delete category?" message="This permanently deletes everything below this category."/></div>}
