import { useCallback, useEffect, useState } from "react";
import axios from "axios";
import { Coins, Pencil, Plus, RefreshCw, Trash2 } from "lucide-react";
import { toast } from "react-toastify";
import LifeSettings from "./life-settings";
import EventKeyGuide from "./event-key-guide";

const blankPackage={name:"",description:"",coins:"",price:"",currency:"NGN",isActive:true,sortOrder:0};
const blankRule={name:"",eventKey:"",type:"reward",amount:"",frequency:"per_event",description:"",isActive:true};
const blankAdjustment={type:"reward",amount:"",description:"",userIds:[]};
const money=(minor,currency)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:currency||"NGN"}).format(Number(minor||0)/100);
const eventKeyFromPhrase=(value)=>String(value||"").trim().toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"");
const fieldClass="w-full rounded-xl border border-slate-200 px-3 py-2.5 outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-100";

function Dialog({title,onClose,onSubmit,busy,children,submitLabel="Save"}){return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-900/45 p-4" onMouseDown={onClose}><form onSubmit={onSubmit} onMouseDown={e=>e.stopPropagation()} className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-xl font-bold">{title}</h2><button type="button" onClick={onClose} className="text-2xl text-slate-400">×</button></div>{children}<div className="mt-6 flex justify-end gap-3"><button type="button" onClick={onClose} className="rounded-xl border px-4 py-2">Cancel</button><button disabled={busy} className="rounded-xl bg-purple-600 px-5 py-2 font-semibold text-white disabled:opacity-60">{busy?"Saving…":submitLabel}</button></div></form></div>}
function Empty({text}){return <div className="py-16 text-center text-slate-400">{text}</div>}

export default function CoinManagement(){
 const [tab,setTab]=useState("packages"),[packages,setPackages]=useState([]),[rules,setRules]=useState([]),[transactions,setTransactions]=useState([]),[users,setUsers]=useState([]),[pagination,setPagination]=useState({page:1,total:0,limit:20});
 const [loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[packageEdit,setPackageEdit]=useState(null),[ruleEdit,setRuleEdit]=useState(null),[adjustment,setAdjustment]=useState(null),[deleting,setDeleting]=useState(null),[search,setSearch]=useState(""),[type,setType]=useState("");
 const load=useCallback(async()=>{setLoading(true);try{const [p,r,t,u]=await Promise.all([axios.get("/admin/coins/packages"),axios.get("/admin/coins/rules"),axios.get(`/admin/coins/transactions?page=${pagination.page}&limit=${pagination.limit}&type=${type}&search=${encodeURIComponent(search)}`),axios.get("/auth/admin/users")]);setPackages(p.data.packages||[]);setRules(r.data.rules||[]);setTransactions(t.data.transactions||[]);setUsers(u.data.users||[]);setPagination(x=>({...x,...t.data.pagination}));}catch(e){toast.error(e.response?.data?.message||"Unable to load coin data.");}finally{setLoading(false)}},[pagination.page,pagination.limit,search,type]);
 useEffect(()=>{const timer=setTimeout(load,search?300:0);return()=>clearTimeout(timer)},[load,search]);
 const editPackage=p=>setPackageEdit(p?{...p,price:(Number(p.price_minor)/100).toFixed(2),isActive:p.is_active,sortOrder:p.sort_order}:blankPackage);
 const editRule=r=>setRuleEdit(r?{...r,eventKey:r.event_key,isActive:r.is_active}:blankRule);
 const savePackage=async e=>{e.preventDefault();setBusy(true);const d=packageEdit,payload={name:d.name,description:d.description||"",coins:Number(d.coins),priceMinor:Math.round(Number(d.price)*100),currency:d.currency.toUpperCase(),isActive:d.isActive,sortOrder:Number(d.sortOrder)||0};try{d.id?await axios.put(`/admin/coins/packages/${d.id}`,payload):await axios.post("/admin/coins/packages",payload);toast.success(`Package ${d.id?"updated":"created"}.`);setPackageEdit(null);load()}catch(x){toast.error(x.response?.data?.message||x.response?.data?.errors?.[0]?.message||"Unable to save package.")}finally{setBusy(false)}};
 const saveRule=async e=>{e.preventDefault();setBusy(true);const d=ruleEdit,payload={name:d.name,eventKey:eventKeyFromPhrase(d.eventKey),type:d.type,amount:Number(d.amount),frequency:d.frequency,description:d.description||"",isActive:d.isActive};try{d.id?await axios.put(`/admin/coins/rules/${d.id}`,payload):await axios.post("/admin/coins/rules",payload);toast.success(`Rule ${d.id?"updated":"created"}.`);setRuleEdit(null);load()}catch(x){toast.error(x.response?.data?.message||x.response?.data?.errors?.[0]?.message||"Unable to save rule.")}finally{setBusy(false)}};
 const saveAdjustment=async e=>{e.preventDefault();if(!adjustment.userIds.length)return toast.error("Select at least one player.");setBusy(true);try{const {data}=await axios.post("/admin/coins/transactions",{userIds:adjustment.userIds,type:adjustment.type,amount:Number(adjustment.amount),description:adjustment.description});toast.success(`${data.count} player${data.count===1?"":"s"} ${adjustment.type==="reward"?"rewarded":"debited"}.`);setAdjustment(null);setTab("transactions");load()}catch(x){toast.error(x.response?.data?.message||x.response?.data?.errors?.[0]?.message||"Unable to update player balances.")}finally{setBusy(false)}};
 const remove=async()=>{setBusy(true);try{await axios.delete(`/admin/coins/${deleting.kind}/${deleting.id}`);toast.success("Deleted successfully.");setDeleting(null);load()}catch(e){toast.error(e.response?.data?.message||"Unable to delete item.")}finally{setBusy(false)}};
 return <div className="min-h-screen bg-slate-50 p-4 sm:p-7"><div className="mx-auto max-w-7xl"><header className="mb-6 flex flex-wrap items-center justify-between gap-4"><div><h1 className="flex items-center gap-2 text-2xl font-black text-slate-900"><Coins className="text-amber-500"/>Coin system</h1><p className="mt-1 text-sm text-slate-500">Manage packages, ledger activity, reward rules and deductions.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>setAdjustment(blankAdjustment)} className="flex items-center gap-2 rounded-xl bg-purple-600 px-4 py-2 text-sm font-bold text-white"><Plus size={16}/>Manual points</button><button onClick={load} className="flex items-center gap-2 rounded-xl border bg-white px-4 py-2 text-sm font-semibold"><RefreshCw size={16}/>Refresh</button></div></header>
 <div className="mb-6 flex gap-2 overflow-x-auto rounded-2xl bg-white p-2 shadow-sm">{[["packages","Packages"],["transactions","Transactions"],["rewards","Reward rules"],["deductions","Deduction rules"]].map(([id,label])=><button key={id} onClick={()=>setTab(id)} className={`whitespace-nowrap rounded-xl px-4 py-2.5 text-sm font-bold ${tab===id?"bg-purple-600 text-white":"text-slate-500 hover:bg-slate-50"}`}>{label}</button>)}</div>
 {tab==="deductions"&&!loading&&<div className="mb-5"><LifeSettings/></div>}
 {tab==="deductions"&&!loading&&<div className="mb-5"><EventKeyGuide/></div>}
 {loading?<div className="rounded-2xl bg-white py-24 text-center text-slate-400">Loading coin system…</div>:tab==="packages"?<section className="rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-bold">Coin packages</h2><button onClick={()=>editPackage(null)} className="flex items-center gap-2 rounded-xl bg-purple-600 px-4 py-2 text-sm font-bold text-white"><Plus size={17}/>New package</button></div>{packages.length?<div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b text-slate-500"><tr><th className="p-3">Package</th><th className="p-3">Coins</th><th className="p-3">Price</th><th className="p-3">Status</th><th className="p-3 text-right">Actions</th></tr></thead><tbody>{packages.map(p=><tr key={p.id} className="border-b last:border-0"><td className="p-3"><b>{p.name}</b><p className="max-w-md text-xs text-slate-400">{p.description||"No description"}</p></td><td className="p-3 font-semibold">{Number(p.coins).toLocaleString()}</td><td className="p-3">{money(p.price_minor,p.currency)}</td><td className="p-3"><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${p.is_active?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-500"}`}>{p.is_active?"Active":"Hidden"}</span></td><td className="p-3"><div className="flex justify-end gap-2"><button onClick={()=>editPackage(p)} className="rounded-lg p-2 text-purple-600 hover:bg-purple-50"><Pencil size={17}/></button><button onClick={()=>setDeleting({kind:"packages",id:p.id,name:p.name})} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div>:<Empty text="No packages yet. Create the first one."/>}</section>:tab==="transactions"?<section className="rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5 flex flex-wrap gap-3"><input value={search} onChange={e=>{setSearch(e.target.value);setPagination(x=>({...x,page:1}))}} placeholder="Search user, email or reference" className={`${fieldClass} max-w-md`}/><select value={type} onChange={e=>{setType(e.target.value);setPagination(x=>({...x,page:1}))}} className={`${fieldClass} max-w-48`}><option value="">All types</option><option value="purchase">Purchase</option><option value="reward">Reward</option><option value="deduction">Deduction</option><option value="adjustment">Adjustment</option></select></div>{transactions.length?<div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b text-slate-500"><tr><th className="p-3">User</th><th className="p-3">Type</th><th className="p-3">Amount</th><th className="p-3">Balance</th><th className="p-3">Description</th><th className="p-3">Date</th></tr></thead><tbody>{transactions.map(t=><tr key={t.id} className="border-b last:border-0"><td className="p-3"><b>{t.user_name}</b><p className="text-xs text-slate-400">{t.user_email}</p></td><td className="p-3 capitalize">{t.type}</td><td className={`p-3 font-bold ${Number(t.amount)>0?"text-emerald-600":"text-red-600"}`}>{Number(t.amount)>0?"+":""}{Number(t.amount).toLocaleString()}</td><td className="p-3">{Number(t.balance_after).toLocaleString()}</td><td className="p-3">{t.description}</td><td className="whitespace-nowrap p-3 text-slate-500">{new Date(t.created_at).toLocaleString()}</td></tr>)}</tbody></table></div>:<Empty text="No matching transactions."/>}<div className="mt-5 flex items-center justify-between text-sm text-slate-500"><span>{pagination.total.toLocaleString()} transactions</span><div className="flex gap-2"><button disabled={pagination.page<=1} onClick={()=>setPagination(x=>({...x,page:x.page-1}))} className="rounded-lg border px-3 py-2 disabled:opacity-40">Previous</button><button disabled={pagination.page*pagination.limit>=pagination.total} onClick={()=>setPagination(x=>({...x,page:x.page+1}))} className="rounded-lg border px-3 py-2 disabled:opacity-40">Next</button></div></div></section>:<RulesPanel rules={rules.filter(r=>r.type===(tab==="rewards"?"reward":"deduction"))} type={tab==="rewards"?"reward":"deduction"} onAdd={()=>editRule({...blankRule,type:tab==="rewards"?"reward":"deduction"})} onEdit={editRule} onDelete={r=>setDeleting({kind:"rules",id:r.id,name:r.name})}/>} </div>
 {packageEdit&&<Dialog title={packageEdit.id?"Edit package":"Create package"} onClose={()=>setPackageEdit(null)} onSubmit={savePackage} busy={busy}>{[["Package name","name","text"],["Description","description","text"],["Number of coins","coins","number"],["Price","price","number"],["Currency","currency","text"],["Display order","sortOrder","number"]].map(([label,key,type])=><label key={key} className="mb-4 block text-sm font-semibold">{label}<input required={!['description'].includes(key)} min={type==="number"?0:undefined} step={key==="price"?"0.01":undefined} type={type} value={packageEdit[key]} onChange={e=>setPackageEdit(x=>({...x,[key]:e.target.value}))} className={`mt-1 ${fieldClass}`}/></label>)}<label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={packageEdit.isActive} onChange={e=>setPackageEdit(x=>({...x,isActive:e.target.checked}))}/>Visible to players</label></Dialog>}
 {ruleEdit&&<Dialog title={ruleEdit.id?"Edit rule":"Create rule"} onClose={()=>setRuleEdit(null)} onSubmit={saveRule} busy={busy}>{[["Rule name","name","text"],["Event key","eventKey","text"],["Amount","amount","number"],["Description","description","text"]].map(([label,key,inputType])=><label key={key} className="mb-4 block text-sm font-semibold">{label}<input required={key!=="description"} min={inputType==="number"?1:undefined} type={inputType} value={ruleEdit[key]} onChange={e=>setRuleEdit(x=>({...x,[key]:e.target.value}))} className={`mt-1 ${fieldClass}`}/></label>)}<label className="mb-4 block text-sm font-semibold">Frequency<select value={ruleEdit.frequency} onChange={e=>setRuleEdit(x=>({...x,frequency:e.target.value}))} className={`mt-1 ${fieldClass}`}><option value="per_event">Every event</option><option value="once">Once per user</option><option value="daily">Once daily</option><option value="weekly">Once weekly</option></select></label><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={ruleEdit.isActive} onChange={e=>setRuleEdit(x=>({...x,isActive:e.target.checked}))}/>Rule active</label></Dialog>}
 {adjustment&&<Dialog title="Manual point adjustment" onClose={()=>setAdjustment(null)} onSubmit={saveAdjustment} busy={busy} submitLabel={adjustment.type==="reward"?"Reward points":"Withdraw points"}><div className="mb-4 grid grid-cols-2 gap-2"><button type="button" onClick={()=>setAdjustment(x=>({...x,type:"reward"}))} className={`rounded-xl border px-4 py-3 font-bold ${adjustment.type==="reward"?"border-emerald-600 bg-emerald-50 text-emerald-700":"text-slate-500"}`}>Reward</button><button type="button" onClick={()=>setAdjustment(x=>({...x,type:"deduction"}))} className={`rounded-xl border px-4 py-3 font-bold ${adjustment.type==="deduction"?"border-red-500 bg-red-50 text-red-600":"text-slate-500"}`}>Withdraw</button></div><label className="mb-4 block text-sm font-semibold">Players<select required multiple size="8" value={adjustment.userIds} onChange={e=>setAdjustment(x=>({...x,userIds:Array.from(e.target.selectedOptions,o=>o.value)}))} className={`mt-1 ${fieldClass}`}>{users.map(u=><option key={u.id} value={u.id}>{u.name} (@{u.username}) — {Number(u.coins_count).toLocaleString()} points</option>)}</select><span className="mt-1 block text-xs font-normal text-slate-400">Use Ctrl/Cmd or Shift to select multiple players.</span></label><button type="button" onClick={()=>setAdjustment(x=>({...x,userIds:x.userIds.length===users.length?[]:users.map(u=>u.id)}))} className="mb-4 text-sm font-bold text-purple-600">{adjustment.userIds.length===users.length?"Clear selection":"Select all players"}</button><label className="mb-4 block text-sm font-semibold">Points per player<input required type="number" min="1" max="1000000" value={adjustment.amount} onChange={e=>setAdjustment(x=>({...x,amount:e.target.value}))} className={`mt-1 ${fieldClass}`}/></label><label className="block text-sm font-semibold">Reason<input required minLength="3" maxLength="500" value={adjustment.description} onChange={e=>setAdjustment(x=>({...x,description:e.target.value}))} placeholder="Reason shown in player history" className={`mt-1 ${fieldClass}`}/></label>{adjustment.type==="deduction"&&<p className="mt-4 rounded-xl bg-amber-50 p-3 text-xs text-amber-700">The entire batch is cancelled if any selected player has insufficient points.</p>}</Dialog>}
 {deleting&&<Dialog title="Confirm deletion" onClose={()=>setDeleting(null)} onSubmit={e=>{e.preventDefault();remove()}} busy={busy} submitLabel="Delete"><p>Delete <b>{deleting.name}</b>? Existing transaction history will remain intact.</p></Dialog>}
 </div>;
}

function RulesPanel({rules,type,onAdd,onEdit,onDelete}){return <section className="rounded-2xl bg-white p-5 shadow-sm"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg font-bold capitalize">{type} rules</h2><p className="text-sm text-slate-500">Rules define amounts and frequency; game events can apply them through the backend ledger service.</p></div><button onClick={onAdd} className="flex items-center gap-2 rounded-xl bg-purple-600 px-4 py-2 text-sm font-bold text-white"><Plus size={17}/>New rule</button></div>{rules.length?<div className="grid gap-4 md:grid-cols-2">{rules.map(r=><article key={r.id} className="rounded-xl border p-4"><div className="flex justify-between gap-3"><div><h3 className="font-bold">{r.name}</h3><code className="text-xs text-purple-600">{r.event_key}</code></div><span className={`h-fit rounded-full px-2 py-1 text-xs font-bold ${r.is_active?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-500"}`}>{r.is_active?"Active":"Paused"}</span></div><p className="mt-3 text-2xl font-black">{type==="reward"?"+":"−"}{Number(r.amount).toLocaleString()} <small className="text-sm text-slate-400">coins</small></p><p className="mt-1 text-sm text-slate-500">{r.description||"No description"} · {r.frequency.replace("_"," ")}</p><div className="mt-4 flex justify-end gap-2"><button onClick={()=>onEdit(r)} className="rounded-lg p-2 text-purple-600 hover:bg-purple-50"><Pencil size={17}/></button><button onClick={()=>onDelete(r)} className="rounded-lg p-2 text-red-500 hover:bg-red-50"><Trash2 size={17}/></button></div></article>)}</div>:<Empty text={`No ${type} rules yet.`}/>}</section>}
